{
  "headline": "FDA's records trace our supply to a plant classified OAI 622 days before the posting",
  "headline_cites": ["D11"],
  "sentences": [
    {
      "text": "FDA first posted the bupivacaine hydrochloride shortage on 2018-02-20 and it remains Current as of 2026-10-21.",
      "cites": ["E54", "D25"]
    },
    {
      "text": "The label for NDC 00409-1159-01 names Hospira, Inc. at FEI 1925262 as a registered plant.",
      "cites": ["E34"]
    },
    {
      "text": "FDA inspection 976095 at that plant ended 2016-06-08 and was classified OAI, 622 days before the shortage posting.",
      "cites": ["D11", "E28"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2017-02-14, 371 days before the posting.",
      "cites": ["D12", "E33"]
    },
    {
      "text": "Another label source, NDC 31722-275-32, names Aspiro Pharma Limited at FEI 3014483338, whose most recent inspection ended 2023-08-11 and was classified VAI.",
      "cites": ["E9", "E45", "E44"]
    },
    {
      "text": "Corvale East has 4.6 days of 2.5 mg/mL 10 mL vials on hand, while Corvale Lakeside has 19.7 days and can spare 19 vials.",
      "cites": ["D1", "D3", "D26"]
    },
    {
      "text": "The rule‑ranked option is to transfer 19 vials from Corvale Lakeside to Corvale East, raising East to 6 days on hand.",
      "cites": ["D26"]
    }
  ]
}
